@props([ 'name' => 'file', 'id' => null, 'label' => null, 'accept' => null, 'multiple' => false, 'help' => null, 'error' => null, 'required' => false, ]) @php $inputId = $id ?: ($name ?: 'ui-file-' . uniqid()); $hasError = $error || ($name && isset($errors) && $errors->has($name)); $errorMessage = $error ?: ($name && isset($errors) ? $errors->first($name) : null); @endphp <div class="ui-form-group"> @if($label) <label for="{{ $inputId }}" class="ui-label">{{ $label }} @if($required) <span class="ui-label-required"> * </span> @endif </label> @endif <div class="ui-file-dropzone" onclick="document.getElementById('{{ $inputId }}').click()"><input type="file" id="{{ $inputId }}" name="{{ $name }}" class="ui-file-input" @if($accept) accept="{{ $accept }}" @endif @if($multiple) multiple @endif @if($required) required @endif {{ $attributes }} onchange="const n = this.files.length > 1 ? this.files.length + ' file dipilih' : (this.files[0]?.name || ''); if(n) this.nextElementSibling.querySelector('.ui-file-name-preview').innerText = n;" /><div><i class="fa-solid fa-cloud-arrow-up" style="font-size: 32px; color: var(--primary); margin-bottom: 8px;"></i><div style="font-size: 14px; font-weight: 600; color: #fff; margin-bottom: 4px;"> Klik atau seret file ke area ini </div><div class="ui-file-name-preview" style="font-size: 12.5px; color: var(--text-muted);">{{ $slot->isNotEmpty() ? $slot : 'Pilih file dari perangkat Anda' }}</div></div></div> @if($hasError) <span class="ui-error-text">{{ $errorMessage }}</span> @elseif($help) <span class="ui-help-text">{{ $help }}</span> @endif </div>